import { metricsClient } from "@dynatrace-sdk/client-classic-environment-v2";

// Function to convert date string to timestamp
function toTimestamp(datetime) {
  return Date.parse(datetime);
}

// Function to fetch metrics
async function obtenerMetricas(selectorMetrica, dt_timeframe_from, dt_timeframe_to) {
  const response = await metricsClient.query({
    acceptType: 'application/json; charset=utf-8',
    from: toTimestamp(dt_timeframe_from).toString(),
    to: toTimestamp(dt_timeframe_to).toString(),
    metricSelector: selectorMetrica,
  });
  return response.result[0]["data"];
}

// Function to transform metrics data to HistogramChartFormat
function transformToHistogramChartFormat(metricasPorAplicacion) {
  const results = {};

  for (let i = 0; i < metricasPorAplicacion.length; i++) {
    const category = metricasPorAplicacion[i].dimensionMap["Apdex category"];
    const timestamps = metricasPorAplicacion[i].timestamps;
    const values = metricasPorAplicacion[i].values;

    for (let j = 0; j < timestamps.length; j++) {
      const timestamp = new Date(timestamps[j]).toISOString();

      if (!results[timestamp]) {
        results[timestamp] = {
          timestamp,
          SATISFIED: 0,
          TOLERATING: 0,
          FRUSTRATED: 0,
        };
      }

      results[timestamp][category] = values[j];
    }
  }

  return Object.values(results);
}

export default async function () {
  const query = 'builtin:apps.other.keyUserActions.count.osAndApdex:filter(and(or(in("dt.entity.device_application_method",entitySelector("type(device_application_method),fromRelationship.isDeviceApplicationMethodOf(type(MOBILE_APPLICATION),entityName.equals(~"'+$Application+'~"))"))))):splitBy("Apdex category"):sort(value(auto,descending))';
  const metricasPorAplicacion = await obtenerMetricas(query, $dt_timeframe_from, $dt_timeframe_to);
  const formattedData = transformToHistogramChartFormat(metricasPorAplicacion);
  return formattedData;
}
