  const response = await metricsClient.query({
    acceptType: 'application/json; charset=utf-8',
    from: toTimestamp(dt_timeframe_from).toString(),
    to: toTimestamp(dt_timeframe_to).toString(),
    metricSelector: selectorMetrica,
  });
  return response.result[0]["data"];
}

// Function to transform metrics data to HistogramChartFormat
function transformToHistogramChartFormat(metricasPorAplicacion) {
  const results = {};

  for (let i = 0; i < metricasPorAplicacion.length; i++) {
    const category = "duration";
    const timestamps = metricasPorAplicacion[i].timestamps;
    const values = metricasPorAplicacion[i].values;

    for (let j = 0; j < timestamps.length; j++) {
      const timestamp = new Date(timestamps[j]).toISOString();

      if (!results[timestamp]) {
        results[timestamp] = {
          timestamp,
        };
      }

      results[timestamp][category] = values[j];
    }
  }

  return Object.values(results);
}

